export const ROCETS_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/rocets-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getRocetsStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(ROCETS_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
